        /// Whether readers see the page. &lt;span pulumi-lang-nodejs="`true`" pulumi-lang-dotnet="`True`" pulumi-lang-go="`true`" pulumi-lang-python="`true`" pulumi-lang-yaml="`true`" pulumi-lang-java="`true`" pulumi-lang-hcl="`true`"&gt;`true`&lt;/span&gt; (the default) publishes after every change; &lt;span pulumi-lang-nodejs="`false`" pulumi-lang-dotnet="`False`" pulumi-lang-go="`false`" pulumi-lang-python="`false`" pulumi-lang-yaml="`false`" pulumi-lang-java="`false`" pulumi-lang-hcl="`false`"&gt;`false`&lt;/span&gt; keeps it a draft and unpublishes a live page.
        /// </summary>
        [Input("published")]
        public Input<bool>? Published { get; set; }

        /// <summary>
        /// The page's address segment (1 to 80 characters, lowercase letters, digits and hyphens). A slug already taken in the collection is an error, never a silent suffix.
        /// </summary>
        [Input("slug")]
        public Input<string>? Slug { get; set; }

        /// <summary>
        /// The space (its id or slug). Changing it replaces the page.
        /// </summary>
        [Input("spaceId")]
        public Input<string>? SpaceId { get; set; }

        /// <summary>
        /// The page's title, 1 to 300 characters.
        /// </summary>
        [Input("title")]
        public Input<string>? Title { get; set; }

        /// <summary>
        /// When the page last changed.
        /// </summary>
        [Input("updatedAt")]
        public Input<string>? UpdatedAt { get; set; }

        /// <summary>
        /// The page's public address, when it has one.
        /// </summary>
        [Input("url")]
        public Input<string>? Url { get; set; }

        /// <summary>
        /// The docs version the page belongs to (up to 40 characters). Defaults to the current version. Changing it replaces the page.
        /// </summary>
        [Input("versionKey")]
        public Input<string>? VersionKey { get; set; }

        public PageState()
        {
        }
        public static new PageState Empty => new PageState();
    }
}
